Lemma wbytes_out (M : word -> option byte) (dst : Z) (bs : list byte) (a : Z) :
  0 <= dst < 2 ^ 64 -> dst + Z.of_nat (length bs) <= 2 ^ 64 -> 0 <= a < 2 ^ 64 -> ~ (dst <= a < dst + Z.of_nat (length bs)) ->
  wbytes M (Z_to_bv 64 dst) bs (Z_to_bv 64 a) = M (Z_to_bv 64 a).
